&lt;div data-page-id=&quot;Gu90dQN8LojGXOxwbLJlZ6Begne&quot; data-lark-html-role=&quot;root&quot; data-docx-has-block-data=&quot;false&quot;&gt;
&lt;h3 class=&quot;heading-3 ace-line old-record-id-doxlgxPksT0HvTPgxV1pKJM3PFg&quot;&gt;Client Relationship Management&lt;/h3&gt;
&lt;ul class=&quot;list-bullet1&quot;&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-doxlgAECVPSuAiMs4j5flWybOzm&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;Serve as the dedicated relationship manager for a portfolio of VIP clients with AUM or trading volume above defined thresholds&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-doxlg6AJja4GYtYVbzb32B8gmdd&quot; data-list=&quot;bullet&quot;&gt;
