&lt;div class=&quot;ace-line ace-line old-record-id-CzjQdI1IWofbWMxmIahu6dAMsjc&quot;&gt;
&lt;div data-page-id=&quot;Q5McdBHqRos9a1xglGGuWZx7sgc&quot; data-docx-has-block-data=&quot;false&quot;&gt;
&lt;div data-page-id=&quot;HkVtdktaboGMelx9svwuFoNSsof&quot; data-lark-html-role=&quot;root&quot; data-docx-has-block-data=&quot;false&quot;&gt;
&lt;div data-page-id=&quot;FyjUdMZIjoV2rwxJqgNuKWoasod&quot; data-lark-html-role=&quot;root&quot; data-docx-has-block-data=&quot;false&quot;&gt;
&lt;h2 class=&quot;heading-2 ace-line old-record-id-doxusxvzyTH4iZpRPTygm6sKzcf&quot;&gt;&lt;strong&gt;Perks &amp;amp; Benefits &lt;/strong&gt;&lt;/h2&gt;
&lt;ul class=&quot;list-bullet1&quot;&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-doxus9Bu8Z2VOqDK5F51723OA8g&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;Competitive total compensation package&lt;/div&gt;
&lt;/li&gt;
